export class AudioFX{constructor(){this.ctx=null;this.enabled=true}unlock(){if(!this.ctx)this.ctx=new (window.AudioContext||window.webkitAudioContext)();this.ctx.resume()}tone(freq=300,dur=.06,type='sine',gain=.07){if(!this.enabled||!this.ctx)return;const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,this.ctx.currentTime);g.gain.setValueAtTime(gain,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.ctx.currentTime+dur);o.connect(g).connect(this.ctx.destination);o.start();o.stop(this.ctx.currentTime+dur)}hit(power=1){this.tone(170+power*90,.05,'triangle',.035)}success(){this.tone(440,.15);setTimeout(()=>this.tone(660,.22),90)}fail(){this.tone(120,.18,'sawtooth',.025)}}
